@startuml

enum PriorityScore {
  HIGH
  LOW
}

class HospitalHouseMD {}

class Patient {
  + signConsent()
  + retractConsent()
}

class Doctor {
  + approveDiagnosis()
  + downgradeTreatment()
}

class Nurse {}

class Illness {
  + priorityScore : PriorityScore
}

class Diagnosis {
  + description : string
}

class Treatment {
  + stage : int
}

class ConsentForm {
  + date : date
}

HospitalHouseMD "1" -- "*" Patient
HospitalHouseMD "1" -- "*" Doctor
HospitalHouseMD "1" -- "*" Nurse
HospitalHouseMD "1" -- "*" Illness

Patient "1" -- "1..*" Doctor : is assigned to
Patient "1" -- "0..*" Diagnosis : has
Patient "1" -- "0..*" Treatment : undergoes
Patient "1" -- "0..1" ConsentForm : provides

Doctor "1" -- "0..*" Diagnosis : makes
Doctor "1" -- "0..*" Treatment : manages

Nurse "0..*" -- "0..*" Treatment : monitors

Illness "1" -- "0..*" Diagnosis : causes
Illness "1" -- "0..*" Treatment : has possible

Diagnosis "1" -- "0..*" Treatment : results in

@enduml

